  3	final class BellmanFord {
  4	    private static final int INF = 100_000_000;
  5	
  6	    private BellmanFord() {
  7	    }
  8	
  9	    static int[] bellmanFord(int vertices, int[][] edgeData, int source) {
 10	        validateInput(vertices, edgeData, source);
 11	        return bellmanFord(vertices, toEdges(edgeData), source);
 12	    }
 13	
 14	    private static int[] bellmanFord(int vertices, Edge[] edges, int source) {
 15	        int[] distances = new int[vertices];
 16	        Arrays.fill(distances, INF);
 17	        distances[source] = 0;
 18	
 19	        for (int pass = 0; pass < vertices - 1; pass++) {
 20	            boolean updated = false;
 21	
 22	            for (Edge edge : edges) {
 23	                if (distances[edge.from] == INF) {
 24	                    continue;
 25	                }
 26	
 27	                int candidateDistance = distances[edge.from] + edge.weight;
 28	                if (candidateDistance < distances[edge.to]) {
 29	                    distances[edge.to] = candidateDistance;
 30	                    updated = true;
 31	                }
 32	            }
 33	
 34	            if (!updated) {
 35	                return distances;
 36	            }
 37	        }
 38	
 39	        for (Edge edge : edges) {
 40	            if (distances[edge.from] != INF
 41	                    && distances[edge.from] + edge.weight < distances[edge.to]) {
 42	                return new int[] {-1};
 43	            }
 44	        }
 45	
 46	        return distances;
 47	    }
 48	
 49	    private static void validateInput(int vertices, int[][] edgeData, int source) {
 50	        if (vertices <= 0) {
 51	            throw new IllegalArgumentException("vertices must be positive");
 52	        }
 53	        if (source < 0 || source >= vertices) {
 54	            throw new IllegalArgumentException("source must be within the vertex range");
 55	        }
 56	        if (edgeData == null) {
 57	            throw new IllegalArgumentException("edges must not be null");
 58	        }
 59	    }
 60	
 61	    private static Edge[] toEdges(int[][] edgeData) {
 62	        Edge[] edges = new Edge[edgeData.length];
 63	        for (int i = 0; i < edgeData.length; i++) {
 64	            int[] edge = edgeData[i];
 65	            if (edge == null || edge.length != 3) {
 66	                throw new IllegalArgumentException("each edge must contain exactly 3 integers");
 67	            }
 68	            edges[i] = new Edge(edge[0], edge[1], edge[2]);
 69	        }
 70	        return edges;
 71	    }
 72	
 73	    private static final class Edge {
 74	        private final int from;
 75	        private final int to;
 76	        private final int weight;
 77	
 78	        private Edge(int from, int to, int weight) {
 79	            this.from = from;
 80	            this.to = to;
 81	            this.weight = weight;
 82	        }
 83	    }
